    const viralSlide2 = document.getElementById("viral-slide-2");
    if (viralSlide2) viralSlide2.innerHTML = `<h3>${t("viral_modal.slide2_title")}</h3><p>${t("viral_modal.slide2_p1")}</p><p>${t("viral_modal.slide2_p2")}</p>`;

